"""Command line interface for pennywise."""

import argparse
import csv
import io
import json
import os
import re
import sys
from datetime import date

from . import ledger
from .ledger import ParseError


def _date_arg(value):
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value, re.ASCII):
        try:
            return date(int(value[:4]), int(value[5:7]), int(value[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError(
        "invalid date %r (expected a real date as YYYY-MM-DD)" % value
    )


def _build_parser():
    p = argparse.ArgumentParser(
        prog="pennywise", description="Read a plain-text household ledger."
    )
    sub = p.add_subparsers(dest="command", metavar="COMMAND")

    s = sub.add_parser("balance", help="print the total balance")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="list entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg)
    s.add_argument("--until", type=_date_arg)
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("add", help="append an entry to a ledger file")
    s.add_argument("file", metavar="FILE")
    # Everything after FILE is taken literally, dash or not: a note such as
    # "-note" must not be read as an option. -h/--help still works as the
    # first argument after "add".
    s.add_argument(
        "words",
        metavar="DATE CATEGORY AMOUNT [NOTE]",
        nargs=argparse.REMAINDER,
        help="the entry, as separate words (the note is one quoted word)",
    )
    s.set_defaults(add_parser=s)

    s = sub.add_parser("export", help="export entries")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
    return p


# Options that take a value, per command. The word after one of these is always
# its value, even when it starts with a dash (a category may be "-misc").
_VALUE_OPTIONS = {
    "balance": (),
    "summary": ("--by",),
    "list": ("--category", "--since", "--until"),
    "export": ("--format",),
}
_FLAG_OPTIONS = ("--json", "--help")


def _is_option(word, known):
    """True if WORD is (a prefix of) an option of the command, so not a value."""
    if word == "-h":
        return True
    if not word.startswith("--") or word == "--":
        return False
    name = word.split("=", 1)[0]
    return any(o.startswith(name) for o in known)


def _prepare_argv(argv):
    """Let a dash-leading option value or FILE through argparse.

    "list F --category -misc" becomes "list F --category=-misc", and
    "balance -x" reads the ledger "-x". Anything after "--" is left alone, and
    so is `add`, which takes its words literally (only a dash-leading FILE right
    after "add" gets a "--" in front of it). A word starting with "--"
    that is not an option stays an error: write such a file name after "--".
    """
    argv = list(argv)
    if argv and argv[0] == "add":
        # add has no options of its own: a single-dash word right after it (other
        # than -h) is the FILE, so the rest of the line is taken as it stands.
        if len(argv) > 1 and argv[1].startswith("-") and not argv[1].startswith("--") \
                and argv[1] not in ("-", "-h"):
            argv.insert(1, "--")
        return argv
    if not argv or argv[0] not in _VALUE_OPTIONS:
        return argv
    values = _VALUE_OPTIONS[argv[0]]
    known = values + _FLAG_OPTIONS
    out = [argv[0]]
    dash_file = None
    seen_file = False
    i = 1
    while i < len(argv):
        word = argv[i]
        i += 1
        if word == "--":
            out.append(word)
            out.extend(argv[i:])
            break
        if word.startswith("--"):
            name = word.split("=", 1)[0]
            matches = [o for o in known if o.startswith(name)]
            if name in known:
                matches = [name]
            if (
                len(matches) == 1
                and matches[0] in values
                and "=" not in word
                and i < len(argv)
                and not _is_option(argv[i], known)
            ):
                word = "%s=%s" % (matches[0], argv[i])
                i += 1
            out.append(word)
        elif word.startswith("-") and word not in ("-", "-h") and not seen_file:
            # An unknown single-dash word, before any FILE: it is the file name.
            dash_file = word
            seen_file = True
        else:
            seen_file = seen_file or not word.startswith("-") or word == "-"
            out.append(word)
    if dash_file is not None:
        if "--" in out:
            out.insert(out.index("--") + 1, dash_file)
        else:
            out.extend(["--", dash_file])
    return out


class _ReadError(Exception):
    pass


class _UsageError(Exception):
    pass


def _add_words(words):
    """Split add's literal words into (date, category, amount, note)."""
    words = list(words)
    # "--" separates options from words; some Python versions leave it in the
    # remainder. Five or more words can only mean it is a separator.
    if len(words) > 4 and "--" in words:
        words.remove("--")
    if not 3 <= len(words) <= 4:
        raise _UsageError(
            "add takes DATE CATEGORY AMOUNT and an optional NOTE "
            "(got %d argument%s)" % (len(words), "" if len(words) == 1 else "s")
        )
    return tuple(words) + ("",) * (4 - len(words))


def _read_ledger_text(path):
    # Plain utf-8: ledger.parse strips the (single) leading BOM itself.
    try:
        if path == "-":
            stdin = sys.stdin
            if stdin is None:
                raise OSError("standard input is closed")
            buf = getattr(stdin, "buffer", None)
            if buf is not None:
                return buf.read().decode("utf-8")
            return stdin.read()
        with open(path, "rb") as f:
            return f.read().decode("utf-8")
    except (OSError, ValueError) as exc:  # ValueError: closed file, bad UTF-8
        raise _ReadError("cannot read %s: %s" % (path, exc)) from None


def _load(path):
    return ledger.parse(_read_ledger_text(path))


def _sorted_entries(entries):
    return sorted(entries, key=lambda e: e.date)  # stable


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": ledger.format_money(e.amount),
        "note": e.note,
    }


def _cmd_balance(args):
    total = ledger.format_money(ledger.balance(_load(args.file)))
    return json.dumps({"balance": total}) + "\n" if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = (
        ledger.by_month(entries) if args.by == "month" else ledger.by_category(entries)
    )
    rows = [(k, ledger.format_money(totals[k])) for k in sorted(totals)]
    if args.json:
        return json.dumps(dict(rows)) + "\n"
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = ledger.filter_entries(
        _load(args.file), args.category, args.since, args.until
    )
    entries = _sorted_entries(entries)
    if args.json:
        return json.dumps([_entry_dict(e) for e in entries]) + "\n"
    return "".join(ledger.format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted_entries(_load(args.file))
    out = io.StringIO()
    w = csv.writer(out, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        w.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return out.getvalue()


def _line_ending(data):
    """The ending of the first line of data (bytes); LF if it has no line break."""
    m = re.search(rb"\r\n|\r|\n", data)
    return m.group(0) if m else b"\n"


def _cmd_add(args):
    date_word, category, amount, note = _add_words(args.words)
    try:
        with open(args.file, "rb") as f:
            existing = f.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        raise _ReadError("cannot read %s: %s" % (args.file, exc)) from None
    # A leading BOM is not content: a BOM-only file is as good as empty.
    body = existing[3:] if existing.startswith(b"\xef\xbb\xbf") else existing
    lineno = len(ledger.split_lines(body.decode("utf-8", "replace"))) + 1

    for name, value in (
        ("date", date_word),
        ("category", category),
        ("amount", amount),
    ):
        if value == "" or re.search(r"[ \t\r\n]", value):
            raise ParseError(lineno, "%s must be a single non-empty word" % name)
    line = "%s %s %s" % (date_word, category, amount)
    if note.strip():
        line += " " + note
    if len(ledger.split_lines(line)) != 1 or re.search(r"[\r\n]", line):
        raise ParseError(lineno, "entry must be a single line")
    entry = ledger.parse_line(line, lineno)

    # Build everything that can fail (printed line, encoded bytes) before the
    # file is touched: a non-zero exit must never follow a change to the file.
    printed = ledger.format_entry(entry) + "\n"
    eol = _line_ending(existing)
    prefix = b"" if not body or body.endswith((b"\n", b"\r")) else eol
    try:
        payload = prefix + printed[:-1].encode("utf-8") + eol
    except UnicodeEncodeError:
        raise ParseError(lineno, "entry is not valid UTF-8 text") from None
    try:
        with open(args.file, "ab") as f:
            f.write(payload)
    except OSError as exc:
        raise _ReadError("cannot write %s: %s" % (args.file, exc)) from None
    return printed


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def _encodable(text, stream):
    """Make text writable to stream: what it cannot encode is backslash-escaped."""
    encoding = getattr(stream, "encoding", None)
    if not encoding:
        return text
    try:
        text.encode(encoding)
    except UnicodeEncodeError:
        return text.encode(encoding, "backslashreplace").decode(encoding)
    except LookupError:
        pass
    return text


def _silence_stdout():
    """Point stdout at devnull so the interpreter's shutdown flush cannot fail."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    # Closed stderr (`2>&-`) leaves sys.stderr as None, and print(file=None) and
    # argparse then fall back to stdout. The brief wants stdout empty on every
    # error path, so the message goes to a sink instead: it is simply dropped.
    err = sys.stderr
    if err is None or getattr(err, "closed", False):
        sys.stderr = io.StringIO()
        try:
            return _main(argv)
        finally:
            sys.stderr = err
    return _main(argv)


def _main(argv):
    parser = _build_parser()
    try:
        args = parser.parse_args(
            _prepare_argv(sys.argv[1:] if argv is None else argv)
        )
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    if args.command is None:
        parser.print_usage(sys.stderr)
        return 2
    # Closed stdout (`>&-`) leaves sys.stdout as None. Decide that before the
    # command runs, so `add` never changes the file and then fails to report it:
    # an I/O failure is exit 2 with nothing done, never exit 1 after a change.
    if sys.stdout is None or getattr(sys.stdout, "closed", False):
        print("pennywise: cannot write output: standard output is closed",
              file=sys.stderr)
        return 2
    try:
        out = _COMMANDS[args.command](args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _ReadError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    except _UsageError as exc:
        args.add_parser.print_usage(sys.stderr)
        print("pennywise add: error: %s" % exc, file=sys.stderr)
        return 2
    try:
        sys.stdout.write(_encodable(out, sys.stdout))
        sys.stdout.flush()
    except BrokenPipeError:
        # Reader closed the pipe early (e.g. `| head -1`). End quietly with
        # success (pattern from the Python docs).
        _silence_stdout()
    except OSError as exc:
        # Any other failure to write (e.g. a full disk). For `add` the file is
        # already changed, so say so; exit 2 (I/O failure), never 1.
        _silence_stdout()
        note = " (the entry was added to the file)" if args.command == "add" else ""
        print("pennywise: cannot write output: %s%s" % (exc.strerror or exc, note),
              file=sys.stderr)
        return 2
    return 0
