def _date_arg(value):
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value, re.ASCII):
        try:
            return date(int(value[:4]), int(value[5:7]), int(value[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError(
        "invalid date %r (expected a real date as YYYY-MM-DD)" % value
    )


