    p = argparse.ArgumentParser(
        prog="pennywise", description="Read a plain-text household ledger."
    )
    sub = p.add_subparsers(dest="command", metavar="COMMAND")

    s = sub.add_parser("balance", help="print the total balance")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="list entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg)
    s.add_argument("--until", type=_date_arg)
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("add", help="append an entry to a ledger file")
    s.add_argument("file", metavar="FILE")
    # Everything after FILE is taken literally, dash or not: a note such as
    # "-note" must not be read as an option. -h/--help still works as the
    # first argument after "add".
    s.add_argument(
        "words",
        metavar="DATE CATEGORY AMOUNT [NOTE]",
        nargs=argparse.REMAINDER,
        help="the entry, as separate words (the note is one quoted word)",
    )
    s.set_defaults(add_parser=s)

    s = sub.add_parser("export", help="export entries")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
