    """Let a dash-leading option value or FILE through argparse.

    "list F --category -misc" becomes "list F --category=-misc", and
    "balance -x" reads the ledger "-x". Anything after "--" is left alone, and
    so is `add`, which takes its words literally (only a dash-leading FILE right
    after "add" gets a "--" in front of it). A word starting with "--"
    that is not an option stays an error: write such a file name after "--".
    """
    argv = list(argv)
    if argv and argv[0] == "add":
        # add has no options of its own: a single-dash word right after it (other
        # than -h) is the FILE, so the rest of the line is taken as it stands.
        if len(argv) > 1 and argv[1].startswith("-") and not argv[1].startswith("--") \
                and argv[1] not in ("-", "-h"):
            argv.insert(1, "--")
        return argv
    if not argv or argv[0] not in _VALUE_OPTIONS:
        return argv
    values = _VALUE_OPTIONS[argv[0]]
    known = values + _FLAG_OPTIONS
    out = [argv[0]]
    dash_file = None
    seen_file = False
    i = 1
    while i < len(argv):
        word = argv[i]
        i += 1
        if word == "--":
            out.append(word)
            out.extend(argv[i:])
            break
        if word.startswith("--"):
            name = word.split("=", 1)[0]
            matches = [o for o in known if o.startswith(name)]
            if name in known:
                matches = [name]
            if (
                len(matches) == 1
